154:     }
155:     let best = Infinity;
156:     position.forEach((spot, index) => {
157:       if (spot) return;
158:       position[index] = 'X';
159:       best = Math.min(best, minimax(position, true, depth + 1));
160:       position[index] = '';
161:     });
162:     return best;
163:   }
