166:     let bestScore = -Infinity;
167:     let choices = [];
168:     position.forEach((spot, index) => {
169:       if (spot) return;
170:       position[index] = 'O';
171:       const score = minimax(position, false);
172:       position[index] = '';
173:       if (score > bestScore) { bestScore = score; choices = [index]; }
174:       else if (score === bestScore) choices.push(index);
175:     });
176:     return choices[Math.floor(Math.random() * choices.length)];
177:   }
